let current = 'es';
export const getLang = () => current;
export const setLang = (lang) => { current = STRINGS[lang] ? lang : 'en'; };

// ?lang= wins, then the saved choice, then the browser languages; English otherwise
export function detectLang() {
  let saved = null;
  try { saved = localStorage.getItem('lang'); } catch { /* storage blocked */ }
  const asked = new URLSearchParams(location.search).get('lang');
  const browser = (navigator.languages ?? [navigator.language]).map((l) => l.slice(0, 2).toLowerCase());
  return [asked, saved, ...browser].find((l) => l && STRINGS[l]) ?? 'en';
}

export function t(key, vars = {}) {
  const text = STRINGS[current][key] ?? STRINGS.en[key] ?? key;
  return text.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
}
